DASHBOARD_HTML = """<!doctype html>
<html><head><title>GPU Lab MCP</title><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
:root{color-scheme:dark;font-family:Inter,system-ui,sans-serif}body{margin:0;background:#09111f;color:#e7edf7}main{max-width:1180px;margin:auto;padding:32px 20px}h1{margin:0;font-size:28px}.sub{color:#9fb0c8}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:14px;margin:24px 0}.card{background:#111d30;border:1px solid #253958;border-radius:12px;padding:18px}.label{font-size:12px;text-transform:uppercase;color:#8da1c0;letter-spacing:.08em}.value{font-size:20px;font-weight:700;margin-top:7px}.ok{color:#51d88a}.error{color:#ff8391}table{width:100%;border-collapse:collapse;background:#111d30;border:1px solid #253958;border-radius:12px;overflow:hidden}th,td{text-align:left;padding:12px;border-bottom:1px solid #203451;vertical-align:top}th{font-size:12px;text-transform:uppercase;color:#8da1c0}.badge{border-radius:99px;padding:3px 8px;font-size:12px;font-weight:700}.success{background:#123e2a;color:#73e7a1}.failure{background:#4b1d2a;color:#ff9ca8}code{white-space:pre-wrap;color:#c6d7f4}#updated{float:right;color:#8da1c0;font-size:13px}</style>
</head><body><main><span id="updated">Connecting...</span><h1>GPU Lab MCP</h1><p class="sub">Streamable MCP endpoint: <code>/mcp</code> - refreshes every 15 seconds</p><section class="grid" id="gpus"></section><h2>Recent activity</h2><table><thead><tr><th>Time</th><th>Action</th><th>Outcome</th><th>Duration</th><th>Arguments / error</th></tr></thead><tbody id="activity"><tr><td colspan="5">Loading...</td></tr></tbody></table></main>
<script>
const esc=x=>String(x??'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
function gpuCard(title,detail,sub){return `<article class="card"><div class="label">${esc(title)}</div><div class="value">${esc(detail||'Unavailable')}</div><div class="sub">${esc(sub||'')}</div></article>`}
async function refresh(){try{const [status,activity]=await Promise.all([fetch('/status').then(r=>r.json()),fetch('/activity').then(r=>r.json())]);let cards=[];for(const i of status.instances||[])cards.push(gpuCard('Vast GPU',i.gpu_model,`${i.id} - ${i.status} - $${i.hourly_price||'?'} / hr`));const l=status.local;if(l)cards.push(gpuCard('Local GPU',l.gpu,l.workspace));document.querySelector('#gpus').innerHTML=cards.join('')||gpuCard('Gateway','No GPUs found','');document.querySelector('#activity').innerHTML=activity.map(x=>`<tr><td>${esc(new Date(x.at).toLocaleString())}</td><td><b>${esc(x.tool)}</b></td><td><span class="badge ${x.outcome==='success'?'success':'failure'}">${esc(x.outcome)}</span></td><td>${esc(x.duration_ms)} ms</td><td><code>${esc(x.error||JSON.stringify(x.arguments))}</code></td></tr>`).join('')||'<tr><td colspan="5">No activity yet.</td></tr>';updated.textContent='Updated '+new Date().toLocaleTimeString()}catch(e){updated.textContent='Connection error: '+e}}
refresh();setInterval(refresh,15000);
</script></body></html>"""
